    double A_in_1[TILE][NP];
#pragma HLS ARRAY_PARTITION variable=A_in_1 complete dim=2
    double A_in_2[TILE][NP];
#pragma HLS ARRAY_PARTITION variable=A_in_2 complete dim=2

