#pragma HLS ARRAY_PARTITION variable=sum_local cyclic factor=2 dim=1

    // Load C4 once into local memory via wide bus.
    double C4_row[NP];
#pragma HLS ARRAY_PARTITION variable=C4_row cyclic factor=2 dim=1
  load_c4_i:
    for (s = 0; s < np; s++) {
      long base = (long)s * np;
      memcpy_wide_bus_read_float(C4_row, C4, base * sizeof(double), np * sizeof(double));
    load_c4_j:
      for (p = 0; p < np; p++) {
