      // ---------------- STORE PHASE ----------------
    store_tile:
      for (i = 0; i < cur_rows; i++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=256
        int idx = cur_t + i;
        int rr = idx / nq;
        int qq = idx % nq;
        long base = ((long)rr * nq + qq) * (long)np;

        // Capture last row into sum_local before writing out.
      capture_sum:
        for (p = 0; p < np; p++) {
