        } else {
          memcpy_wide_bus_write_float(A, A_out_2[i], base * sizeof(double), np * sizeof(double));
        }
      }

      // Update sum with the last processed row of this tile (wide bus write).
      memcpy_wide_bus_write_float(sum, sum_local, 0, np * sizeof(double));
    }
}
